def count_binary_seq(n):
    """
    Write a function to find the count of all binary sequences of length 2n
    such that sum of first n bits is same as sum of last n bits.
    """
    dp = {}

    def solve(index, sum_so_far):
        if index == n:
            return 1 if sum_so_far == 0 else 0

        if (index, sum_so_far) in dp:
            return dp[(index, sum_so_far)]

        count = solve(index + 1, sum_so_far + 1) + solve(index + 1, sum_so_far - 1)
        dp[(index, sum_so_far)] = count
        return count

    total_count = 0
    for first_n_sum in range(n + 1):
        total_count += solve(0, -first_n_sum) * solve(0, first_n_sum)

    return total_count

