def get_max_sum(n):
    """
    Finds the maximum sum possible by using the given equation
    f(n) = max( (f(n/2) + f(n/3) + f(n/4) + f(n/5)), n).

    Args:
        n: An integer.

    Returns:
        The maximum sum possible.
    """
    if n <= 0:
        return 0
    if n == 1:
        return 1

    cache = {}

    def calculate_max_sum(num):
        if num in cache:
            return cache[num]

        if num <= 0:
            return 0
        if num == 1:
            return 1

        term1 = 0
        if num / 2 >= 1:
            term1 = calculate_max_sum(num / 2)
        if num / 3 >= 1:
            term1 += calculate_max_sum(num / 3)
        if num / 4 >= 1:
            term1 += calculate_max_sum(num / 4)
        if num / 5 >= 1:
            term1 += calculate_max_sum(num / 5)

        result = max(term1, num)
        cache[num] = result
        return result

    return calculate_max_sum(n)

