def sequence(n):
    """
    Finds the nth number in the Newman-Conway sequence.

    The Newman-Conway sequence is defined as follows:
    a(1) = 1
    a(2) = 2
    a(n) = a(n-1) + a(n-2) if n > 2 and n is not a power of 2
    a(n) = 2 * a(n/2) if n is a power of 2

    Args:
        n: The index of the number to find in the sequence (starting from 1).

    Returns:
        The nth number in the Newman-Conway sequence.
    """
    if n == 1:
        return 1
    if n == 2:
        return 2

    def is_power_of_two(num):
        if num <= 0:
            return False
        while num % 2 == 0:
            num //= 2
        return num == 1

    if is_power_of_two(n):
        return 2 * sequence(n // 2)
    else:
        return sequence(n - 1) + sequence(n - 2)

