def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    primes = []
    i = 2
    while len(primes) < 3 and i < 100:
        if is_prime(i):
            primes.append(i)
        i += 1

    if len(primes) < 3:
        return False

    product = 1
    for prime in primes:
        product *= prime

    if product == a:
        return True
    else:
        return False

