def colon_tuplex(tuplex, m, n):
    """
    Get a colon of a tuple.
    For example:
    colon_tuplex((1, 2, 3, 4, 5), 1, 3) == (2, 3)
    colon_tuplex((1, 2, 3, 4, 5), 0, 5) == (1, 2, 3, 4, 5)
    colon_tuplex((1, 2, 3, 4, 5), -1, 3) == (2, 3)
    """
    if m < 0:
        m = 0
    if n > len(tuplex):
        n = len(tuplex)
    if m >= n:
        return ()
    return tuplex[m:n]

