def set_left_most_unset_bit(n):
    """Given an integer n, set the left most unset bit.
    For example:
    set_left_most_unset_bit(10) == 10
    set_left_most_unset_bit(7) == 7
    set_left_most_unset_bit(0) == 1
    """
    if n == 0:
        return 1

    msb = 0
    temp = n
    while temp > 0:
        temp >>= 1
        msb += 1

    for i in range(msb, -1, -1):
        if (n & (1 << i)) == 0:
            return n | (1 << i)
    return n

