def count_binary_seq(n):
    """
    Find the count of all binary sequences of length 2n such that the sum of the first n bits is the same as the sum of the last n bits.

    Args:
        n (int): The number of bits in each half of the sequence.

    Returns:
        int: The count of binary sequences satisfying the condition.
    """

    if n == 0:
        return 1

    dp = {}

    def solve(index, current_sum):
        if index == n:
            return 1 if current_sum == 0 else 0

        if (index, current_sum) in dp:
            return dp[(index, current_sum)]

        count = solve(index + 1, current_sum + 1) + solve(index + 1, current_sum)
        dp[(index, current_sum)] = count
        return count

    total_count = 0
    for i in range(n + 1):
        total_count += solve(0, i) * solve(0, i)
    return total_count

