def get_max_sum(n):
    """
    Finds the maximum sum possible by using the given equation f(n) = max( (f(n/2) + f(n/3) + f(n/4) + f(n/5)), n).

    Args:
      n: An integer.

    Returns:
      The maximum sum possible.
    """
    if n <= 0:
        return 0
    if n == 1:
        return 1

    dp = {}

    def calculate_max_sum(num):
        if num in dp:
            return dp[num]

        if num <= 0:
            return 0
        if num == 1:
            return 1

        term1 = (calculate_max_sum(num / 2) +
                 calculate_max_sum(num / 3) +
                 calculate_max_sum(num / 4) +
                 calculate_max_sum(num / 5))

        result = max(term1, num)
        dp[num] = result
        return result

    return calculate_max_sum(n)

