def count_binary_seq(n):
    """
    Given an integer n, find the count of all binary sequences of length 2n
    such that sum of first n bits is same as sum of last n bits.

    For example:
    count_binary_seq(2) == 6
    count_binary_seq(3) == 20
    """

    dp = {}

    def solve(index, sum_so_far, n):
        if index == n:
            return 1

        if (index, sum_so_far) in dp:
            return dp[(index, sum_so_far)]

        count = solve(index + 1, sum_so_far + 0, n) + solve(index + 1, sum_so_far + 1, n)
        dp[(index, sum_so_far)] = count
        return count

    first_n_sum_counts = solve(0, 0, n)

    total_count = 0
    for i in range(n * 2 + 1):
        if i <= n:
            count_i = 0

            dp = {}
            def solve_second(index, sum_so_far, n, target):
                if index == n:
                    if sum_so_far == target:
                        return 1
                    else:
                        return 0

                if (index, sum_so_far) in dp:
                    return dp[(index, sum_so_far)]

                count = solve_second(index + 1, sum_so_far + 0, n, target) + solve_second(index + 1, sum_so_far + 1, n, target)
                dp[(index, sum_so_far)] = count
                return count

            count_i = solve_second(0,0,n,i)
            total_count += count_i * count_i
    return total_count

